I am explicitly asking you to run a workflow. Call the Workflow tool with exactly this script, unchanged, and do not load any skill first. When it completes, reply with only the total.

```js
export const meta = {
  name: 'count-lines',
  description: 'Count lines of a.txt and b.txt in parallel, then sum them',
  phases: [{ title: 'Count', detail: 'one agent per file' }, { title: 'Sum', detail: 'add the two counts' }],
}
const NUM = { type: 'object', properties: { n: { type: 'number' } }, required: ['n'] }
phase('Count')
const [a, b] = await parallel([
  () => agent('Count the lines in ./a.txt with wc -l. Return just the number.', { label: 'count a.txt', phase: 'Count', model: 'haiku', schema: NUM }),
  () => agent('Count the lines in ./b.txt with wc -l. Return just the number.', { label: 'count b.txt', phase: 'Count', model: 'haiku', schema: NUM }),
])
phase('Sum')
const total = await agent(`Add ${a && a.n} and ${b && b.n}. Return just the sum.`, { label: 'sum', phase: 'Sum', model: 'haiku', schema: NUM })
return { total: total && total.n }
```
